 const compareRows=(a,b)=>{let cmp;if(s.sort==='amount')cmp=a.r.amount-b.r.amount;else if(s.sort==='date')cmp=a.r.date.localeCompare(b.r.date);else cmp=String(a.r[s.sort]).localeCompare(String(b.r[s.sort]),'ru',{sensitivity:'base',numeric:true});return cmp*s.direction||a.index-b.index};
 function sortHead(key,label,extra=''){return `<th class="${extra}" aria-sort="${s.sort===key?(s.direction===1?'ascending':'descending'):'none'}"><button class="fm-sort" type="button" data-sort="${key}" aria-label="Сортировать: ${label}">${label}<span class="fm-sort-arrow" aria-hidden="true">${s.sort===key?(s.direction===1?'↑':'↓'):'↕'}</span></button></th>`}
